-- f-tutor t-55: the definition version a sound's lesson was checked against, apart from the panel's, which a new
-- panel moves on. Generated by `prisma migrate diff`, keeping only this change: the generator also emits drops for the
-- hand-written user FKs and the vector/full-text indexes it cannot model (B13), which are stripped.

-- AlterTable
ALTER TABLE "user_sound" ADD COLUMN     "lessonVersion" INTEGER;

-- A lesson saved before this column was checked against the version its sound was saved on.
UPDATE "user_sound" SET "lessonVersion" = "definitionVersion" WHERE "lesson" IS NOT NULL;
